    var t0=null, D=1500; function ease(t){ return 1-Math.pow(1-t,3); }
    function step(ts){ if(t0===null) t0=ts; var k=Math.min(1,(ts-t0)/D); var v=Math.round(before+(after-before)*ease(k)); num.innerHTML=coinHTML(shop,v); if(k<.999) requestAnimationFrame(step); else { num.innerHTML=coinHTML(shop,after); bx.classList.add('settled'); } }
