    var items=[]; th.forEach(function(t){ items.push({d:t.created_at,kind:'THREAD',where:t.title,body:'',n:t.posts_n,open:function(){ go('thread',{id:t.id}); }}); }); po.forEach(function(x){ if(TT[x.thread_id]&&TT[x.thread_id].created_at===x.created_at) return; items.push({d:x.created_at,kind:'POST',where:(TT[x.thread_id]||{}).title||'a thread',body:x.body,open:function(){ go('thread',{id:x.thread_id}); }}); });
