    reps.forEach(function(r){ var p=byId[r.parent_id]; var c=el('div','card'); var row=el('div','row'); var who=r.user_id&&PC[r.user_id]?PC[r.user_id]:{handle:r.author_name||'Guest'}; if(r.user_id) row.appendChild(nameRow(who,r.created_at)); else { row.appendChild(el('span','hch',r.author_name||'Guest')); row.appendChild(el('span','hcago',ago(r.created_at))); } if(r._new) row.appendChild(el('span','sptag','NEW')); c.appendChild(row); var b=el('div','body'); b.textContent=r.body; c.appendChild(b); if(p){ var q=el('div','q'); q.textContent='on your comment: \u201c'+String(p.body||'').slice(0,120)+(String(p.body||'').length>120?'\u2026':'')+'\u201d'; c.appendChild(q); var wl=el('div','row'); wl.innerHTML=workLink(p.book_id); c.appendChild(wl); } BD.appendChild(c); });
